-- 1. FAQ 8 ข้อ (20260827-1500_om_faq.sql) — ลงท้าย "ค่ะ" (ข้อ 6) · แก้ข้อมูลผิด:
--    "สิทธิ์ยกยอดได้ ไม่หมดอายุ" ขัดกับสิทธิ์จากแพ็กเกจที่ซื้อเพิ่มซึ่งหมดอายุตามสัญญา (entitlement-expiry.ts)
--    อ้างเมนู "MyHome" / "แจ้งซ่อม / นัดบริการ" / "นัดของฉัน" ที่ไม่มีหน้าจริง — ลูกค้ามีแค่ "บ้านของฉัน" กับ FAQ
--    ภาษาพูด: ช่วงฝุ่นเยอะ · หลุดประกัน · ตัดสิทธิ์ · แล้วแต่ว่าวันไหนมาทีหลัง
UPDATE dbo.om_faq SET answer = N'ดูได้ที่เมนู "บ้านของฉัน" ในแชตนี้ จะแสดงสิทธิ์คงเหลือของบ้านแต่ละหลัง สิทธิ์ตามสัญญาซื้อบ้านไม่มีวันหมดอายุ ส่วนสิทธิ์จากแพ็กเกจที่ซื้อเพิ่มใช้ได้ภายในระยะสัญญาค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'สิทธิ์ล้างแผงของฉันเหลือกี่ครั้ง' AND answer = N'ดูได้ที่เมนู "MyHome" ในแชตนี้ — จะแสดงสิทธิ์คงเหลือของบ้านแต่ละหลัง สิทธิ์ยกยอดได้ ไม่หมดอายุ';
UPDATE dbo.om_faq SET answer = N'แนะนำปีละ 2 ครั้ง โดยเฉพาะหลังหน้าฝนและช่วงที่มีฝุ่นมาก เพราะแผงที่สกปรกผลิตไฟได้ลดลงถึง 20% ค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'ควรล้างแผงบ่อยแค่ไหน' AND answer = N'แนะนำปีละ 2 ครั้ง โดยเฉพาะช่วงหลังหน้าฝนและช่วงฝุ่นเยอะ แผงที่สกปรกทำให้ผลิตไฟลดลงได้ถึง 20%';
UPDATE dbo.om_faq SET answer = N'ไม่แนะนำค่ะ เพราะเสี่ยงตกจากหลังคา และอาจทำให้แผงเสียหายจนไม่อยู่ในเงื่อนไขการรับประกัน ควรให้ทีมช่างที่มีอุปกรณ์และน้ำ DI สำหรับล้างแผงเป็นผู้ดูแล', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'ล้างแผงเองได้ไหม' AND answer = N'ไม่แนะนำ เพราะเสี่ยงต่อการตกจากหลังคาและอาจทำให้แผงเสียหายจนหลุดประกัน ควรให้ทีมช่างที่มีอุปกรณ์ล้างด้วยน้ำ DI';
UPDATE dbo.om_faq SET answer = N'มี 3 รายการ: ประกันงานติดตั้ง 2 ปี · ประกันอินเวอร์เตอร์ 5 ปี · ประกันแผงโซลาร์ 10 ปี นับจากวันเริ่มประกัน ดูวันสิ้นสุดได้ที่เมนู "บ้านของฉัน" ค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'ประกันของฉันครอบคลุมอะไรบ้าง' AND answer = N'มี 3 รายการ: ประกันติดตั้ง 2 ปี · ประกันอินเวอร์เตอร์ 5 ปี · ประกันแผง 10 ปี นับจากวันเริ่มประกัน ดูวันหมดของแต่ละรายการได้ที่เมนู "MyHome"';
UPDATE dbo.om_faq SET answer = N'นับจากวันติดตั้งหรือวันโอนบ้าน โดยใช้วันที่ช้ากว่าค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'วันเริ่มประกันนับจากวันไหน' AND answer = N'นับจากวันติดตั้งหรือวันโอนบ้าน แล้วแต่ว่าวันไหนมาทีหลัง';
UPDATE dbo.om_faq SET answer = N'เมื่อถึงรอบล้าง เจ้าหน้าที่จะโทรนัดวันและเวลาที่สะดวก หรือพิมพ์แจ้งเจ้าหน้าที่ในแชตนี้ได้ ระบบจะหักสิทธิ์ 1 ครั้งเมื่อทีมช่างให้บริการเสร็จค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'จองนัดล้างแผงอย่างไร' AND answer = N'กดเมนู "แจ้งซ่อม / นัดบริการ" เลือกวันและช่วงเวลาที่สะดวก ระบบจะตัดสิทธิ์เมื่อทีมช่างเข้าปฏิบัติงานเสร็จ';
UPDATE dbo.om_faq SET answer = N'ได้ค่ะ กรุณาแจ้งเจ้าหน้าที่ในแชตนี้ล่วงหน้าอย่างน้อย 1 วัน', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'เลื่อนหรือยกเลิกนัดได้ไหม' AND answer = N'ได้ โดยแจ้งล่วงหน้าอย่างน้อย 1 วันทำการ ผ่านเมนูนัดของฉันหรือแชตกับเจ้าหน้าที่';
UPDATE dbo.om_faq SET answer = N'ตรวจสอบก่อนว่าแผงสกปรกหรือมีเงาบังหรือไม่ หากล้างแล้วยังผลิตไฟได้น้อยผิดปกติ แจ้งเจ้าหน้าที่เพื่อนัดตรวจระบบได้ค่ะ', updated_at = SYSDATETIMEOFFSET()
 WHERE question = N'ไฟฟ้าที่ผลิตได้ลดลง ทำอย่างไร' AND answer = N'ตรวจสอบก่อนว่าแผงสกปรกหรือมีเงาบังหรือไม่ หากล้างแล้วยังผลิตได้น้อยผิดปกติ แจ้งเจ้าหน้าที่เพื่อนัดตรวจระบบ';
GO

-- 2. หมายเหตุท้ายใบเสนอราคา (20261014-1600) — "ขอสงวนสิทธิ์" ความหมายผิด (ไม่ได้สงวนสิทธิ์อะไร แค่บอกว่าราคารวมอะไร)
--    ใบเสนอราคาที่ออกไปแล้วแช่หมายเหตุไว้ในใบ (terms_text) ไม่เปลี่ยนตาม
UPDATE dbo.om_package_notes
   SET body = N'ราคานี้รวมเฉพาะค่าแรงและค่าเครื่องมือที่ใช้ในการทำงาน ไม่รวมค่าอะไหล่ที่ใช้ในการซ่อมแซม', updated_at = SYSDATETIMEOFFSET()
 WHERE body = N'ใบเสนอราคานี้ขอสงวนสิทธิ์เฉพาะค่าแรงและเครื่องมือที่ใช้ในการทำงานเท่านั้น ไม่รวมค่าอะไหล่ที่ใช้ในการซ่อมแซม';
GO

-- 3. ใบตรวจรับงาน (20260916-1200_om_job_form.sql) — รายการที่ขึ้นในใบบริการ PDF ของลูกค้า
UPDATE dbo.om_job_form_item SET label_th = N'รางเดินสายไฟ (Wireway)' WHERE label_th = N'ราง Wire way';
-- ชื่อแบบฟอร์มฝั่งช่าง — ตามคำกลาง: แบบฟอร์มที่ช่างกรอก = "ใบตรวจรับงาน" · PDF ลูกค้า = "ใบบริการ" (service-doc.ts ใช้คำนี้คงที่แล้ว)
UPDATE dbo.om_job_form SET label_th = N'ใบตรวจรับงาน' WHERE label_th = N'ใบตรวจรับงาน / ใบบริการ';
GO
